const OperationTimeline = ({ history }) => {
  const sortedHistory = useMemo(() => {
    return [...history].sort((a, b) => {
      const aTime = a.timestamp?.toDate?.() || new Date(a.timestamp);
      const bTime = b.timestamp?.toDate?.() || new Date(b.timestamp);
      return bTime - aTime;
    });
  }, [history]);

  return (
    <div className="bg-gray-50 rounded-xl p-4">
      <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
        <FiTrendingUpIcon className="mr-2 text-indigo-500" />
        Operation Timeline
      </h3>
      
      {sortedHistory.length > 0 ? (
        <div className="space-y-4">
          {sortedHistory.map((record, index) => {
            const timestamp = record.timestamp?.toDate?.() || new Date(record.timestamp);
            const oldStatusConfig = STATUS_CONFIG[record.oldStatus] || STATUS_CONFIG.pending;
            const newStatusConfig = STATUS_CONFIG[record.newStatus] || STATUS_CONFIG.pending;
            
            return (
              <div key={record.id || index} className="flex items-start bg-white rounded-lg p-4 shadow-sm border border-gray-200">
                <div className="flex flex-col items-center mr-4 mt-1">
                  <div className={`w-4 h-4 rounded-full border-2 border-white shadow-sm ${newStatusConfig.badgeColor}`} />
                  {index !== sortedHistory.length - 1 && <div className="w-0.5 h-8 bg-gray-200 my-1" />}
                </div>
                <div className="flex-1">
                  <div className="flex justify-between items-start flex-wrap gap-2">
                    <div className="flex items-center flex-wrap gap-2">
                      <span className="font-semibold text-gray-900">
                        {MACHINE_OPERATIONS[record.operation]?.name || record.operation}
                      </span>
                      <span className="text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded-full">
                        Item {record.itemIndex + 1}
                      </span>
                    </div>
                    <span className="text-sm text-gray-500 bg-gray-50 px-2 py-1 rounded">
                      {timestamp.toLocaleString()}
                    </span>
                  </div>
                  <div className="flex items-center mt-2 flex-wrap gap-2">
                    <StatusBadge status={record.oldStatus} />
                    <FiArrowRight className="text-gray-400 mx-1" size={14} />
                    <StatusBadge status={record.newStatus} />
                  </div>
                  {record.notes && (
                    <p className="text-sm text-gray-600 mt-2 bg-gray-50 p-2 rounded border border-gray-200">
                      {record.notes}
                    </p>
                  )}
                  <p className="text-xs text-gray-500 mt-2">
                    By: {record.updatedBy?.name || record.userName || 'Unknown User'}
                    {record.updatedBy?.role && ` (${record.updatedBy.role})`}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="text-center py-8">
          <FiActivity className="mx-auto h-12 w-12 text-gray-300" />
          <p className="text-gray-500 mt-2">No operation history found for this item</p>
        </div>
      )}
    </div>
  );
};

